function conditionDetail(id){const c=CONDITION_CATALOG.find(x=>x.id===id);if(!c)return;$('detail-body').innerHTML=`<h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><h3>Model-derived mechanisms</h3>${c.effects.map(e=>`<p><b>${esc(e.mechanismId)}</b><br>Affected: ${esc(e.nutrients.join(', '))}<br>Effect: ${esc(e.type.replaceAll('_',' '))}; stage: ${esc(e.stage)}<br>Evidence class: ${esc(e.evidenceClass)}; source: ${esc(e.source)}<br><small>${esc(e.assumption)}</small></p>`).join('')}<p class="muted">This is an educational model boundary, not a diagnosis or medical recommendation.</p>`;$('detail').showModal()}
function detail(key){const x=target(key),v=total().nutrients[key],absorbed=absorptionEstimate(key,v,state.settings.gastricAcid);const estimate=absorbed?`<div><b>Absorption estimate</b><p>${absorbed.sources.map(([name,gross,range])=>`${name}: gross ${f(gross,x.unit)} → ${f(range.min,absorbed.unit)}–${f(range.max,absorbed.unit)}`).join('<br>')}<br><b>Total estimated absorbed: ${f(absorbed.total.min,absorbed.unit)}–${f(absorbed.total.max,absorbed.unit)}</b><br><small>${absorbed.assumption}</small></p></div>`:`<div><b>Absorption / conversion</b><p>Quantitative absorption not modeled. Bioaccessible, systemic, converted, and active stages remain unmodeled rather than zero.</p></div>`;$('detail-body').innerHTML=translateMarkup(`<span class="label">${x.model.replace('_',' ')}</span><h2>${key.replace('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}</h2><p><b>Actual gross intake: ${f(v.total,x.unit)}</b></p><div class="details-list"><div><b>Reference markers</b><p>RDA: ${x.rda??'Not established'} ${x.unit}<br>EAR/AR: ${x.ear??'Not available'}<br>Optimal: ${x.optimalMin??'Not available'}–${x.optimalMax??'Not available'}<br>UL: ${x.ul??'Not established'}</p></div><div><b>Food, form & preparation</b><p>${v.contributions.map(c=>`${esc(c.food)}: ${f(c.amount,x.unit)} (${esc(c.formId)}; ${esc(c.preparation)})`).join('<br>')}</p></div>${dataQuality(key)}${estimate}</div><h3>Evidence & limitations</h3><p>${esc(x.explanation)}</p><p class="muted">Evidence class: source database measurement / explicitly bounded model assumption. Confidence is low for modeled absorption; no intracellular pool or clinical conclusion is inferred.</p>`,state.language);$('detail').showModal()}
function signals(){const t=total();const html=state.meal.length?`<div class="signal"><b>${f(t.energy,'kcal')}</b><span class="muted">meal energy</span></div>${(()=>{const fiber=state.meal.reduce((a,x)=>a+(x.food?.nutrients?.fiber??0)*x.grams/100,0),ab=absorbedCalories(t.energy,fiber,t.antinutrients?.lectin_load?.total??0);return `<div class="signal"><b>${f(ab.kcal,'kcal')}</b><span class="muted">calories absorbed (~${ab.pct}%)</span></div>`})()}${lowFatWarning(t.fat,t.nutrients)?`<div class="signal"><b class="warning">Under 5 g fat</b><span class="muted">Vitamins A, D, E and K absorb poorly without dietary fat.</span></div>`:''}${Object.entries(t.nutrients).slice(0,3).map(([k,v])=>`<div class="signal"><b>${k.replace('_',' ')} <span class="warning">${f(v.total,target(k).unit)}</span></b><span class="muted">actual intake</span></div>`).join('')}`:`<div class="signal"><b>No meal loaded</b><span class="muted">Add food to begin.</span></div>`;$('signals').innerHTML=translateMarkup(html,state.language)}
async function init(){try{const r=await fetch('./canonical-foods.json');if(!r.ok)throw Error(`Canonical USDA dataset failed to load (HTTP ${r.status})`);state.data=await r.json();if(state.data?.status!=='complete'||state.data?.foods?.length!==87)throw Error('Canonical USDA dataset is incomplete');for(const x of state.data.foods)x.origin??={region:'US',country:'United States',type:'whole',measured:true,label:'USDA',greek:false};try{const e=await fetch('./extra-foods.json');if(e.ok){const d=await e.json();for(const [id,name,category,prep,nutrients,source,region,country,type,measured,label,greek,fdcId] of d.rows){const ev=id.replace('-',':').replace('usda:','fdc:');const provenance={};for(const [k,v] of Object.entries(nutrients))provenance[k]={source,evidenceId:ev,unit:d.units[k],amountPer100g:v};state.data.foods.push({id,fdcId:fdcId??undefined,name,category,preparations:[{method:prep,evidenceId:ev}],nutrients,provenance,source:{name:source,official:!!measured},origin:{region,country,type,measured:!!measured,label,greek:!!greek}})}}}catch{}await mergeProfiles();const saved=repository.load();for(const x of saved.customFoods??[])if(!state.data.foods.some(y=>y.id===x.id))state.data.foods.push(x);Object.assign(state,saved,{data:state.data,language:saved.settings.language??'en',region:saved.settings.region??'auto',customFoods:saved.customFoods??[]});$('language').value=state.language;navRender();render();$('quick-add').onclick=()=>route('builder');$('open-analysis').onclick=()=>route('analysis');$('menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');$('nav').addEventListener('click',e=>{if(e.target.closest('button'))document.querySelector('.sidebar').classList.remove('open')});$('language').onchange=e=>{state.language=e.target.value;persist();navRender();render()};$('close').onclick=()=>$('detail').close()}catch(e){notice(`Unable to load food data: ${e.message}`)}}
init();

/* Scientific UI contract: Mechanism recognized, but no defensible individual quantitative coefficient is applied. Ulcerative colitis state; bariatric surgery does not create a generic surgery multiplier; remaining length and adaptation are not converted into numeric coefficients. */

async function mergeProfiles(){try{const r=await fetch('./food-profiles.json');if(r.ok)mergeFoodProfiles(state.data,await r.json())}catch{}}
function foodById(id){return state.data.foods.find(x=>x.id===id)}
function originItem(item,forms){return originItemRaw({...item,food:foodById(item.food?.id)??item.food},forms)}
function antinutrientTotals(meal){return antiRaw(meal.map(x=>({...x,food:foodById(x.food?.id)??x.food})))}
function profileLine(food){const p=profileSummary(food);return p?`<small class="muted">Profile: ${p.measured} measured · ${p.estimated} estimated · ${p.unknown} not measured</small>`:''}
function dataQuality(key){const rows=state.meal.map(x=>{const food=foodById(x.food?.id)??x.food,st=profileStatus(food,key);return st&&st.code!=='M'&&st.code!=='Z'?`${esc(food.name)}: ${esc(st.label)}${st.ref?' — '+esc(st.ref):''}`:null}).filter(Boolean);return rows.length?`<div><b>Data quality</b><p>${rows.join('<br>')}</p></div>`:''}
